-- Disposable seeded local database only. Every fixture change rolls back.
\set ON_ERROR_STOP on
begin;
create function pg_temp.check_it(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; end $$;
create function pg_temp.denied(q text,expected text) returns void language plpgsql as $$ begin begin execute q; exception when others then if position(expected in sqlerrm)>0 then return; end if; raise exception 'Wrong refusal: %',sqlerrm; end; raise exception 'Unexpected success: %',q; end $$;
create temp table f(k text primary key,v uuid); grant all on f to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000002',true);
insert into f values('regular',fn_record_meter_reading('55555555-0000-0000-0000-000000000001',100,now(),gen_random_uuid()));
insert into f values('partial',fn_record_meter_reading('55555555-0000-0000-0000-000000000002',100,now(),gen_random_uuid()));
insert into f values('direct',fn_record_meter_reading('55555555-0000-0000-0000-000000000003',100,now(),gen_random_uuid()));
insert into f values('covered',fn_record_meter_reading('55555555-0000-0000-0000-000000000004',100,now(),gen_random_uuid()));
insert into f values('integer',fn_record_meter_reading('55555555-0000-0000-0000-000000000005',100,now(),gen_random_uuid()));
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000001',true);
select fn_post_bill_amount(v,case k when 'regular' then 249.40 when 'partial' then 199.25 when 'direct' then 349.40 when 'covered' then 99.40 else 100 end,fn_ph_today()+1,now(),gen_random_uuid()) from f;
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000003',true);
select fn_pondo_entry(1000,'opening','Synthetic opening cash',gen_random_uuid());
insert into f values('receipt',fn_record_payment(array[(select v from f where k='regular')],array[250::numeric],300,now(),'cccccccc-0000-0000-0000-000000000071'));
select pg_temp.check_it((select sum(amount)=1000.60 from pondo_ledger),'Regular receipt credits 60 centavos, not the cash change');
select pg_temp.check_it((select change_due=50 from payment_transactions where id=(select v from f where k='receipt')),'Change is not reserve money');
select fn_record_payment(array[(select v from f where k='regular')],array[250::numeric],300,now(),'cccccccc-0000-0000-0000-000000000071');
select pg_temp.check_it((select count(*)=1 from pondo_ledger where kind='rounding'),'Receipt retry credits once');
select pg_temp.denied(format('select fn_record_payment(array[%L::uuid],array[249::numeric],300,now(),%L)',(select v from f where k='regular'),'cccccccc-0000-0000-0000-000000000071'),'conflicts');
select fn_record_remit_handover(date_trunc('month',fn_ph_today())::date);
select pg_temp.check_it((select sum(amount)=1000.60 from pondo_ledger),'Recording remittance does not credit rounding again');
select pg_temp.check_it((select to_boheco=249.40 from remit_handovers),'Only cooperative cash is remitted');
insert into f values('partial1',fn_record_payment(array[(select v from f where k='partial')],array[100::numeric],100,now(),gen_random_uuid()));
select pg_temp.check_it((select sum(amount)=1000.60 from pondo_ledger),'No rounding before cooperative amount is collected');
reset role;
update payments set paid_at=now()-interval '2 seconds' where transaction_id=(select v from f where k='partial1');
set local role authenticated;
insert into f values('partial2',fn_record_payment(array[(select v from f where k='partial')],array[99.50::numeric],100,now(),gen_random_uuid()));
select pg_temp.check_it((select sum(amount)=1000.85 from pondo_ledger),'Crossing cooperative amount credits only actual 25-cent rounding');
reset role;
update payments set paid_at=now()-interval '1 second' where transaction_id=(select v from f where k='partial2');
set local role authenticated;
select fn_record_payment(array[(select v from f where k='partial')],array[0.50::numeric],1,now(),gen_random_uuid());
select fn_record_payment(array[(select v from f where k='integer')],array[100::numeric],100,now(),gen_random_uuid());
select pg_temp.check_it((select sum(amount)=1001.35 from pondo_ledger),'Final partial credits remaining rounding; integer bill adds none');
select pg_temp.denied($q$select fn_pondo_entry(1,'rounding','Invented credit',gen_random_uuid())$q$,'Invalid reserve fund entry');
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000002',true);
insert into f values('trip',fn_close_boheco_trip(date_trunc('month',fn_ph_today())::date));
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000003',true);
select fn_allocate_boheco_trip((select v from f where k='trip'),array[(select v from f where k='covered')],array[100::numeric],'33333333-0000-0000-0000-000000000002');
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000002',true);
select fn_confirm_boheco_payment((select v from f where k='direct'),349.40,'ROUNDING-DIRECT',now(),'Synthetic evidence',gen_random_uuid());
select pg_temp.check_it((select sum(amount)=901.95 from pondo_ledger),'Direct payment creates no cashier or reserve credit');
select fn_confirm_boheco_payment((select v from f where k='covered'),99.40,'ROUNDING-COVERED',now(),'Synthetic evidence',gen_random_uuid());
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000003',true);
insert into f values('repayment',fn_record_payment(array[(select v from f where k='covered')],array[100::numeric],100,now(),'cccccccc-0000-0000-0000-000000000072'));
select fn_record_payment(array[(select v from f where k='covered')],array[100::numeric],100,now(),'cccccccc-0000-0000-0000-000000000072');
select pg_temp.check_it((select sum(amount)=1001.95 from pondo_ledger),'Covered repayment restores full cash including rounding exactly once');
select pg_temp.check_it(not exists(select 1 from pondo_ledger where kind='rounding' and transaction_id=(select v from f where k='repayment')),'Repayment has no extra rounding credit');
select pg_temp.denied($q$select fn_pondo_entry(-1,'correction','Cashier cannot correct',gen_random_uuid())$q$,'Only Admin');
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000001',true);
select fn_pondo_entry(-601.95,'correction','Actual counted cash is 400','cccccccc-0000-0000-0000-000000000073');
select fn_pondo_entry(-601.95,'correction','Actual counted cash is 400','cccccccc-0000-0000-0000-000000000073');
select pg_temp.check_it((select sum(amount)=400 from pondo_ledger),'Admin can correct cash below salary reservation; retry changes nothing');
select pg_temp.denied($q$select fn_pondo_entry(-401,'correction','Cannot record negative cash',gen_random_uuid())$q$,'Insufficient');
select set_config('request.jwt.claim.sub','33333333-0000-0000-0000-000000000003',true);
select pg_temp.denied($q$select fn_pondo_entry(-1,'withdrawal','Reserved salary',gen_random_uuid())$q$,'Insufficient');
select pg_temp.denied($q$select fn_pay_reader_compensation(date_trunc('month',fn_ph_today())::date,'33333333-0000-0000-0000-000000000002')$q$,'insufficient');
reset role;
select pg_temp.check_it(not has_function_privilege('anon','public.fn_record_payment(uuid[],numeric[],numeric,timestamptz,uuid)','execute'),'Anonymous collection denied');
-- Simulate an older regular receipt whose rounding was already included in
-- opening cash. A retry must not add money to a historical receipt.
delete from pondo_ledger where kind='rounding' and transaction_id=(select v from f where k='receipt');
set local role authenticated;
select fn_record_payment(array[(select v from f where k='regular')],array[250::numeric],300,now(),'cccccccc-0000-0000-0000-000000000071');
select pg_temp.check_it(not exists(select 1 from pondo_ledger where kind='rounding' and transaction_id=(select v from f where k='receipt')),'Older receipt retries do not backfill unreviewed cash');
rollback;
